-- STRUCTURE ONLY (no rows): extra legacy tables the UNCHANGED KOSIPA CI2 application touches while booting, logging in and rendering the
-- screens exercised by the FA-03A legacy runtime harness. Generated by integration/kosipa-full-access/legacy-runtime/discover-structure.mjs
-- from SHOW CREATE TABLE on the local 30 Sep 2026 staging copy (read-only account). AUTO_INCREMENT counters removed. __KOSIPA_DB__ is
-- replaced by the stack script; nothing here ever runs against a real-data database.

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`ref_hist_akses_users` (
  `id_histori` int(11) NOT NULL AUTO_INCREMENT,
  `id_user` int(11) DEFAULT NULL,
  `datum` datetime DEFAULT NULL,
  `id_session` varchar(50) DEFAULT NULL,
  `ip_user` varchar(50) DEFAULT NULL,
  `datum_logout` datetime DEFAULT NULL,
  PRIMARY KEY (`id_histori`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`db_currency` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `currency_name` varchar(100) NOT NULL,
  `currency` varchar(100) NOT NULL,
  `currency_code` varchar(50) NOT NULL,
  `symbol` varchar(50) NOT NULL,
  `cd_usr` int(11) NOT NULL,
  `cd` datetime NOT NULL,
  `ud_usr` int(11) NOT NULL,
  `ud` datetime NOT NULL,
  `status` int(11) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`ref_site` (
  `id_ref_site` int(11) NOT NULL AUTO_INCREMENT,
  `kodesite` varchar(50) DEFAULT NULL,
  `nama` varchar(100) DEFAULT NULL,
  `address` text NOT NULL,
  `jenis_site` varchar(30) DEFAULT NULL,
  `kodesite_induk` int(11) DEFAULT NULL,
  `flag` varchar(100) DEFAULT NULL,
  `deleted` enum('false','true') DEFAULT 'true',
  `timezone` varchar(50) NOT NULL,
  `date_format` varchar(50) NOT NULL,
  `time_format` varchar(50) NOT NULL,
  `currency_id` int(11) NOT NULL,
  `currency_placement` varchar(50) NOT NULL,
  `round_off` int(11) NOT NULL,
  `logo` varchar(100) NOT NULL,
  `version` varchar(50) NOT NULL,
  PRIMARY KEY (`id_ref_site`) USING BTREE,
  UNIQUE KEY `XPKref_site` (`id_ref_site`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`m_group_anggota` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL,
  `name` varchar(50) NOT NULL,
  `status` int(11) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`m_status_anggota` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `status_anggota_code` varchar(20) DEFAULT NULL,
  `status_anggota_name` varchar(50) DEFAULT NULL,
  `status_anggota_remarks` varchar(150) DEFAULT NULL,
  `is_active` varchar(150) DEFAULT '0',
  `cd` datetime DEFAULT NULL,
  `cd_usr` varchar(50) DEFAULT NULL,
  `ud` datetime DEFAULT NULL,
  `ud_usr` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`template_id_card` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=COMPACT;

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`business_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(50) NOT NULL,
  `value` longtext NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `__KOSIPA_DB__`.`orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `order_code` varchar(50) NOT NULL,
  `verification_code` varchar(191) NOT NULL DEFAULT '0',
  `customer_id` varchar(15) DEFAULT NULL,
  `id_anggota` int(11) NOT NULL,
  `nik_kar` varchar(50) DEFAULT NULL,
  `customer_type` varchar(10) DEFAULT NULL,
  `seller_id` bigint(20) DEFAULT NULL,
  `seller_is` varchar(191) DEFAULT NULL,
  `payment_status` varchar(15) NOT NULL DEFAULT 'unpaid',
  `order_status` varchar(50) NOT NULL DEFAULT 'pending',
  `payment_method` varchar(100) DEFAULT NULL,
  `transaction_ref` varchar(30) DEFAULT NULL,
  `order_group_id` varchar(191) NOT NULL DEFAULT 'def-order-group',
  `discount_amount` double NOT NULL DEFAULT 0,
  `discount_type` varchar(30) DEFAULT NULL,
  `coupon_code` varchar(191) DEFAULT NULL,
  `order_amount` double NOT NULL DEFAULT 0,
  `is_pause` varchar(20) NOT NULL DEFAULT '0',
  `cause` varchar(191) DEFAULT NULL,
  `shipping_method_id` bigint(20) NOT NULL DEFAULT 0,
  `shipping_address` text DEFAULT NULL,
  `shipping_cost` double(8,2) NOT NULL DEFAULT 0.00,
  `shipping_address_data` text DEFAULT NULL,
  `shipping_type` varchar(191) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `delivery_man_id` bigint(20) DEFAULT NULL,
  `deliveryman_charge` double NOT NULL DEFAULT 0,
  `expected_delivery_date` date DEFAULT NULL,
  `order_note` text DEFAULT NULL,
  `billing_address` bigint(20) unsigned DEFAULT NULL,
  `billing_address_data` text DEFAULT NULL,
  `order_type` varchar(191) NOT NULL DEFAULT 'default_type',
  `extra_discount` double(8,2) NOT NULL DEFAULT 0.00,
  `extra_discount_type` varchar(191) DEFAULT NULL,
  `checked` tinyint(1) NOT NULL DEFAULT 0,
  `delivery_type` varchar(191) DEFAULT NULL,
  `delivery_service_name` varchar(191) DEFAULT NULL,
  `third_party_delivery_tracking_id` varchar(191) DEFAULT NULL,
  `ppob` int(11) NOT NULL,
  `ppob_type` varchar(50) DEFAULT NULL,
  `status_ppob` varchar(100) DEFAULT NULL,
  `tgl_pengambilan` datetime DEFAULT NULL,
  `tgl_bayar` datetime DEFAULT NULL,
  `sales_due` double(18,2) DEFAULT NULL,
  `import_local` int(1) NOT NULL,
  `admin` double(18,2) NOT NULL,
  `post_method` varchar(50) DEFAULT NULL,
  `jw` int(11) NOT NULL,
  `in_proses` int(11) NOT NULL COMMENT '0 : SUCCESS ,1: PROSESS',
  `tr_id` bigint(20) NOT NULL,
  `jml_bulan` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `customer_id` (`customer_id`,`seller_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
